@import 'tailwindcss';
@import './shared/design/tokens.css';

@theme inline {
  --font-sans: var(--eternal-typography-family-web-sans);
  --font-mono: var(--eternal-typography-family-web-mono);
  --font-serif: var(--eternal-typography-family-web-serif);
}

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Explicit device preference: remove costly blur without changing media palettes. */
html[data-visual-effects='reduced'] [class*='backdrop-blur'],
html[data-visual-effects='reduced'] [style*='backdrop-filter'] {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

html[data-visual-effects='reduced'] .eternal-glass {
  background-color: var(--eternal-semantic-surface-opaque);
  box-shadow: none;
}

html {
  scrollbar-gutter: stable;
}

/* Eliminate scrollbar gutter and overflow lines in Game Mode and Fullscreen */
html.game-mode-active,
body.game-mode-active,
:fullscreen,
::backdrop,
:root:fullscreen,
html:fullscreen,
body:fullscreen {
  overflow: hidden !important;
  scrollbar-gutter: auto !important;
  scrollbar-width: none !important;
  background-color: var(--eternal-color-canvas-immersive) !important;
}

html.game-mode-active::-webkit-scrollbar,
body.game-mode-active::-webkit-scrollbar,
:fullscreen::-webkit-scrollbar,
html:fullscreen::-webkit-scrollbar,
body:fullscreen::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

body {
  margin: 0;
  background-color: var(--eternal-color-canvas-body);
}

.bg-radial-gradient {
  background-image: radial-gradient(
    circle at 20% 40%,
    rgba(88, 28, 135, 0.15) 0%,
    rgba(0, 0, 0, 0) 50%
  );
}

* {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.14) transparent;
}

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.14);
  border-radius: 9999px;
  transition: background-color 0.2s ease-in-out;
}

::-webkit-scrollbar-thumb:hover,
::-webkit-scrollbar-thumb:active {
  background: rgba(255, 255, 255, 0.45);
}

::-webkit-scrollbar-button {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

.custom-scrollbar {
