@layer utilities {
  .skeleton-shimmer {
    background: linear-gradient(
      100deg,
      rgba(255, 255, 255, 0.04) 20%,
      rgba(255, 255, 255, 0.09) 40%,
      rgba(255, 255, 255, 0.04) 60%
    );
    background-size: 200% 100%;
    animation: shimmer 1.6s ease-in-out infinite;
    border-radius: 6px;
  }

  @keyframes shimmer {
    0% {
      background-position: 150% 0;
    }

    100% {
      background-position: -50% 0;
    }
  }

  .animate-fadeIn {
    animation: fadeIn 150ms ease-out;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: scale(0.96);
    }

    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  .animate-menuIn {
    animation: menuIn 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes menuIn {
    from {
      opacity: 0;
      transform: scale(0.9) translateY(4px);
    }

    to {
      opacity: 1;
      transform: scale(1) translateY(0);
    }
  }

  .animate-popIn {
    animation: popIn 280ms cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  .animate-slideInRight {
    animation: slideInRight 260ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes slideInRight {
    from {
      transform: translateX(100%);
    }
    to {
      transform: translateX(0);
    }
  }

  .animate-fadeInOverlay {
    animation: fadeInOverlay 220ms ease-out;
  }

  @keyframes fadeInOverlay {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes shake {
    0%,
    100% {
      transform: translateX(0);
    }
    20%,
    60% {
      transform: translateX(-4px);
    }
    40%,
    80% {
      transform: translateX(4px);
    }
  }

  .animate-shake {
    animation: shake 0.35s ease-in-out;
  }

  @keyframes popIn {
    0% {
      opacity: 0;
      transform: scale(0.3);
    }

    60% {
      opacity: 1;
      transform: scale(1.15);
    }

    100% {
      opacity: 1;
      transform: scale(1);
    }
  }

  .animate-badgeExpand {
    animation: badgeExpand 260ms cubic-bezier(0.16, 1, 0.3, 1) 90ms both;
  }

  @keyframes badgeExpand {
    0% {
      opacity: 0;
      transform: scale(0.6) translateX(6px);
    }
    100% {
      opacity: 1;
      transform: scale(1) translateX(0);
    }
  }

  .animate-badgeCollapse {
    animation: badgeCollapse 220ms cubic-bezier(0.16, 1, 0.3, 1) 60ms both;
  }

  @keyframes badgeCollapse {
    0% {
      opacity: 0;
      transform: scale(0.5);
    }
    100% {
      opacity: 1;
      transform: scale(1);
    }
  }

  .animate-reactionBounce {
    animation: reactionBounce 350ms cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  @keyframes reactionBounce {
    0% {
      transform: scale(1);
    }

    35% {
      transform: scale(1.35);
    }

    65% {
      transform: scale(0.92);
    }

    100% {
      transform: scale(1);
    }
  }

  .animate-slideUp {
    animation: slideUp 220ms cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  @keyframes slideUp {
    0% {
      opacity: 0;
      transform: translateY(6px);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-typingDot {
    animation: typingDot 1.2s ease-in-out infinite;
  }

  @keyframes typingDot {
    0%,
    60%,
    100% {
      transform: translateY(0);
      opacity: 0.5;
    }

    30% {
      transform: translateY(-4px);
      opacity: 1;
    }
  }

  .animate-slideInRight {
    animation: slideInRight 220ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes slideInRight {
    from {
      opacity: 0;
      transform: translateX(24px);
    }

    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  .animate-jumpHighlight {
    animation: jumpHighlight 1.5s ease-out;
  }

  @keyframes jumpHighlight {
    0% {
      background-color: rgba(168, 85, 247, 0.35);
      box-shadow:
        0 0 25px rgba(168, 85, 247, 0.5),
        inset 0 0 15px rgba(168, 85, 247, 0.25);
    }

    50% {
      background-color: rgba(168, 85, 247, 0.2);
      box-shadow: 0 0 15px rgba(168, 85, 247, 0.3);
    }

    100% {
      background-color: transparent;
      box-shadow: none;
    }
  }

  .animate-dateJumpPulse {
    animation: dateJumpPulse 1.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }

  @keyframes dateJumpPulse {
    0% {
      transform: scale(1);
      box-shadow: 0 0 0 rgba(168, 85, 247, 0);
      border-color: rgba(255, 255, 255, 0.1);
    }

    25% {
      transform: scale(1.06);
      box-shadow:
        0 0 25px rgba(168, 85, 247, 0.8),
        0 0 10px rgba(147, 51, 234, 0.9);
      border-color: rgba(168, 85, 247, 0.8);
      background-color: rgba(30, 25, 45, 0.95);
      color: #ffffff;
    }

    60% {
      transform: scale(1.03);
      box-shadow: 0 0 18px rgba(168, 85, 247, 0.5);
      border-color: rgba(168, 85, 247, 0.5);
    }

    100% {
      transform: scale(1);
      box-shadow: none;
      border-color: rgba(255, 255, 255, 0.1);
    }
  }

  .animate-modalPop {
    animation: modalPop 200ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes modalPop {
    from {
      opacity: 0;
      transform: scale(0.92) translateY(6px);
    }

    to {
      opacity: 1;
      transform: scale(1) translateY(0);
    }
  }

  .animate-slideOutRight {
    animation: slideOutRight 180ms cubic-bezier(0.4, 0, 1, 1) forwards;
  }

  @keyframes slideOutRight {
    from {
      opacity: 1;
      transform: translateX(0);
    }

    to {
      opacity: 0;
      transform: translateX(24px);
    }
  }

  .animate-slideInLeft {
    animation: slideInLeft 220ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes slideInLeft {
    from {
      opacity: 0;
      transform: translateX(-24px);
    }

    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  .animate-slideOutLeft {
    animation: slideOutLeft 180ms cubic-bezier(0.4, 0, 1, 1) forwards;
  }

  @keyframes slideOutLeft {
    from {
      opacity: 1;
      transform: translateX(0);
    }

    to {
      opacity: 0;
      transform: translateX(-24px);
    }
  }

  .animate-shake {
    animation: shake 400ms cubic-bezier(0.36, 0.07, 0.19, 0.97);
  }

  @keyframes shake {
    10%,
    90% {
      transform: translateX(-1px);
    }

    20%,
    80% {
      transform: translateX(2px);
    }

    30%,
    50%,
    70% {
      transform: translateX(-5px);
    }

    40%,
    60% {
      transform: translateX(5px);
    }
  }

  @keyframes liveEqualizer {
    0%,
    100% {
      transform: scaleY(0.25);
    }
    50% {
      transform: scaleY(1);
    }
  }

  @keyframes equalizerBar {
    0%,
    100% {
      height: 4px;
    }
    50% {
      height: 16px;
    }
  }

  .animate-equalizerBar {
    animation: equalizerBar 0.8s ease-in-out infinite;
  }

  @keyframes marquee-ticker {
    0%,
    20% {
      transform: translateX(0);
    }
    80%,
    100% {
      transform: translateX(calc(-1 * var(--marquee-dist, 40px)));
    }
  }

  /* Gummy gelatin squishy breathing animation */
  @keyframes gummySquish {
    0%,
    100% {
      transform: scale(1, 1);
    }
    30% {
      transform: scale(0.988, 1.022);
    }
    60% {
      transform: scale(1.012, 0.985);
    }
    85% {
      transform: scale(0.994, 1.01);
    }
  }

  .animate-gummy-squish {
    animation: gummySquish 2.4s ease-in-out infinite;
    transform-origin: center bottom;
  }

  /* Prisma chromatic flowing gradient */
  @keyframes prismaFlow {
    0% {
      background-position: 0% 50%;
    }
    100% {
      background-position: 200% 50%;
    }
  }

  .animate-prisma-flow {
    background-size: 200% 100% !important;
    animation: prismaFlow 4s linear infinite;
  }

  /* Neon moving border flow */
  @keyframes neonFlow {
    0% {
      stroke-dashoffset: 100;
    }
    100% {
      stroke-dashoffset: 0;
    }
  }

  .animate-neon-flow {
    animation: neonFlow 4.5s linear infinite;
  }

  /* Cloud wave horizontal flowing animation */
  @keyframes cloudWave {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  .animate-cloud-wave {
    animation: cloudWave 5s linear infinite;
  }

  /* Halo floating bobbing animation */
  @keyframes haloFloat {
    0%,
    100% {
      transform: translateY(0px) rotate(-6deg);
    }
    50% {
      transform: translateY(-3px) rotate(-4deg);
    }
  }

  .animate-halo-float {
    animation: haloFloat 2.8s ease-in-out infinite;
  }

  /* Hacker terminal cursor blink */
  @keyframes terminalCursorBlink {
    0%,
    49% {
      opacity: 1;
    }
    50%,
    100% {
      opacity: 0;
    }
  }

  .animate-terminal-cursor {
    animation: terminalCursorBlink 0.85s infinite;
  }
}

/* ==========================================================================
   Chat Text Effects (Discord Style)
   ========================================================================== */

/* 1. Gradient Effect */
.msg-effect-gradient {
  background: linear-gradient(135deg, #ec4899 0%, #a855f7 50%, #38bdf8 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  display: inline-block;
  max-width: 100%;
}

/* Protected elements inside gradient text: emojis, images, svgs */
.msg-effect-gradient .emoji,
.msg-effect-gradient img,
.msg-effect-gradient [data-emoji='true'],
.msg-effect-gradient svg {
  -webkit-text-fill-color: initial !important;
  background: none !important;
  display: inline-block;
}

/* Selection highlight fix for transparent gradient text */
.msg-effect-gradient::selection,
.msg-effect-gradient *::selection {
  -webkit-text-fill-color: #ffffff !important;
  background: rgba(168, 85, 247, 0.45) !important;
}

/* Hyperlinks and mentions inside gradient text */
.msg-effect-gradient a {
  -webkit-text-fill-color: #38bdf8 !important;
  text-decoration: underline !important;
}

.msg-effect-gradient a:hover {
  -webkit-text-fill-color: #7dd3fc !important;
}

.msg-effect-gradient .mention,
.msg-effect-gradient .mention-link {
  -webkit-text-fill-color: #c084fc !important;
  font-weight: 600;
}

/* 2. Neon Glow Effect */
.msg-effect-neon {
  text-shadow:
    0 0 5px currentColor,
    0 0 12px currentColor,
    0 0 22px rgba(168, 85, 247, 0.8),
    0 0 35px rgba(147, 51, 234, 0.6);
}

/* 3. Cartoon 3D Pop / Comic Effect */
.msg-effect-cartoon {
  font-weight: 700;
  text-shadow:
    -1px -1px 0 #000000,
    1px -1px 0 #000000,
    -1px 1px 0 #000000,
    1px 1px 0 #000000,
    2px 2px 0 #000000,
    3px 3px 0 rgba(0, 0, 0, 0.75);
}

/* 4. Highlight / Marker Effect */
.msg-effect-highlight {
  text-shadow:
    0 0 8px rgba(52, 211, 153, 0.7),
    0 2px 0 #047857;
}

/* 5. Gummy / Jelly 3D Pastel Effect */
.msg-effect-gummy {
  font-weight: 700;
  text-shadow:
    0 2px 0 #db2777,
    0 4px 6px rgba(219, 39, 119, 0.45),
    0 -1px 1px rgba(255, 255, 255, 0.6);
}

/* 6. Prism / Chromatic Dispersion Effect */
.msg-effect-prism {
  text-shadow:
    -1.75px 0px 1px #f43f5e,
    1.75px 0px 1px #06b6d4,
    0px 1.5px 1px #10b981;
}

/* ==========================================================================
   Story Text & Layer Animations (Instagram / Apple Liquid Glass)
   ========================================================================== */
@keyframes storyFloat {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

@keyframes storyBounce {
  0%,
  100% {
    transform: scale(1);
  }
  40% {
    transform: scale(1.08) translateY(-4px);
  }
  60% {
    transform: scale(0.96) translateY(2px);
  }
}

@keyframes storyGlow {
  0%,
  100% {
    filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.4));
  }
  50% {
    filter: drop-shadow(0 0 20px rgba(168, 85, 247, 0.9))
      drop-shadow(0 0 35px rgba(236, 72, 153, 0.8));
  }
}

@keyframes storyWave {
  0%,
  100% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(2deg) translateY(-2px);
  }
  75% {
    transform: rotate(-2deg) translateY(2px);
  }
}

@keyframes storyTypewriterCursor {
  0%,
  100% {
    border-color: currentColor;
  }
  50% {
    border-color: transparent;
  }
}

.story-anim-float {
  animation: storyFloat 3s ease-in-out infinite;
}

.story-anim-bounce {
  animation: storyBounce 1.8s cubic-bezier(0.34, 1.56, 0.64, 1) infinite;
}

.story-anim-glow {
  animation: storyGlow 2.2s ease-in-out infinite;
}

.story-anim-wave {
  animation: storyWave 2.8s ease-in-out infinite;
}

.story-anim-typewriter {
  border-right: 2px solid currentColor;
  animation: storyTypewriterCursor 0.8s step-end infinite;
}

/* Keep final CSS states and animation-end cleanup while removing movement.
   Pending controls expose text/aria-busy independently of their spinner. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
    scroll-behavior: auto !important;
  }
}

